// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(address actor, address victim, bytes32 role) public {
        vm.assume(actor != victim);
        vm.prank(actor);
        bool ok;
        try c.renounceRole(role, victim) {
            ok = true;
        } catch {
            ok = false;
        }
        // Rule: renouncing a role for an account other than the caller must always revert.
        assertTrue(!ok, "renounceRole for a third party must revert");
    }
}
